def affected(arr) -> bool:
    # ORIGINAL returns the largest descent index (or -1); MUTANT always returns -1.
    # They differ when ORIGINAL finds a descent, or when ORIGINAL raises while
    # MUTANT does not (incomparable elements). If len() itself fails, both raise
    # the same error, so the result is not affected.
    try:
        n = len(arr)
    except Exception:
        return False
    try:
        for i in range(n - 1, 0, -1):
            if not arr[i] >= arr[i - 1]:
                return True
        return False
    except Exception:
        return True
